import { defineConfig } from 'tsup';

/**
 * One self-contained file for Supabase Edge Functions (Deno): every dependency is bundled, Node built-ins stay `node:` imports, and the
 * output is written where the Supabase CLI looks for the function. pdfkit and exceljs stay outside the file and are loaded by Deno from npm (pdfkit reads its font files from its own package folder, which a bundle cannot carry).
 */
const banner = [
  '// @ts-nocheck',
  '// Generated by `npm run build:edge -w @solar/api` from apps/api/src. Do not edit.',
  "import { createRequire as __createRequire } from 'node:module';",
  "import { fileURLToPath as __fileURLToPath } from 'node:url';",
  "import { dirname as __dirname_of } from 'node:path';",
  'const require = __createRequire(import.meta.url);',
  'const __filename = __fileURLToPath(import.meta.url);',
  'const __dirname = __dirname_of(__filename);',
].join('\n');

const VERSIONS = { pdfkit: '0.15.2', exceljs: '4.4.0' } as const;

export default defineConfig({
  entry: { index: 'src/edge.ts' },
  format: ['esm'],
  platform: 'node',
  target: 'es2022',
  clean: false,
  outDir: '../../supabase/functions/api',
  outExtension: () => ({ js: '.ts' }),
  noExternal: [/.*/],
  splitting: false,
  sourcemap: false,
  minify: true,
  banner: { js: banner },
  esbuildPlugins: [{
    name: 'npm-specifiers',
    setup(build) {
      build.onResolve({ filter: /^(pdfkit|exceljs)$/ }, (args) => ({ path: 'npm:' + args.path + '@' + VERSIONS[args.path as keyof typeof VERSIONS], external: true }));
    },
  }],
});
